    if(d.LED_ON==='1'||d.LED_ON==='0'){$('ledOn').checked=d.LED_ON==='1';}
    const compat={SUPPORTED:'硬件可用',CONFLICT_OLD_PLUGIN:'旧灯控残留：请清理并重启设备',REBOOT_REQUIRED:'已清除旧启动项，请从F50后台重启后再开启',UNSUPPORTED:'未发现支持的 RGB LED 接口'}[d.LED_COMPAT]||'检测中';
    $('ledState').textContent=(d.LED_ON==='1'?'已开启':'已关闭')+' · '+compat+' · 当前：'+(d.LED_COLOR||'OFF')+(d.LED_TEST&&d.LED_TEST!=='NONE'?' · 手动测试：'+d.LED_TEST:'');
